import{z as A,x as m,o as e,c as B,q as i,j as s,D as t,d as r,s as n,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"稳健优化","description":"","frontmatter":{"title":"稳健优化","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/robust-portfolio-opt.md","filePath":"quant/robust-portfolio-opt.md","lastUpdated":1791413859000}'),d={name:"quant/robust-portfolio-opt.md"};function p(u,a,h,f,D,C){const o=m("Mermaid");return e(),B("div",null,[a[2]||(a[2]=i('<h1 id="稳健优化" tabindex="-1">稳健优化 <a class="header-anchor" href="#稳健优化" aria-label="Permalink to &quot;稳健优化&quot;">​</a></h1><div class="epigraph"><p>不确定集里最坏的 $\\mu$ 决定仓位；集合太大，最优变成不交易，集合太小，又回到被估计误差支配的 Markowitz。</p><footer>—— Goldfarb and Iyengar, Robust Portfolio Selection Problems, Mathematics of Operations Research, 2003</footer></div><p><a href="/quant/bayesian-portfolio">上一课</a>对后验取期望。稳健优化的缺口是<strong>对不确定集取最坏</strong>：\\(\\max_w \\min_{\\mu\\in\\mathcal U} w^\\top\\mu-\\frac{\\gamma}{2}w^\\top\\Sigma w\\)。前沿 <a href="/quant/wasserstein-dro-portfolio">Wasserstein DRO</a> 是分布鲁棒的一种；本课写经典盒/椭圆不确定集，并接到已有 <a href="/quant/cvar-opt">CVaR 优化</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>贝叶斯需要先验。交易员若不愿写先验，仍想避免「历史最佳资产杠杆」，可以把 \\(\\mu\\) 限制在样本均值附近的椭圆 \\(\\{(\\mu-\\hat\\mu)^\\top\\Sigma_\\mu^{-1}(\\mu-\\hat\\mu)\\le\\chi^2\\}\\)，然后做 maximin。问题是 \\(\\chi^2\\)（集合半径）与贝叶斯先验方差同样是风险偏好：半径按「95% 置信」去填，往往会过度保守，权重接近最小方差。半径应按<strong>样本外效用</strong>校准，不是按名义置信水平。</p><p>盒约束 \\(|\\mu_i-\\hat\\mu_i|\\le\\delta_i\\) 会把权重推向 \\(\\delta\\) 小（估得准）的资产，可能过度集中于债券——这也是特征，要检查 \\(\\delta\\) 是否只是波动的倒数。</p><p><span class="marginnote">maximin 的直觉：先假设自己的估计全错，在错得最离谱的那组参数下，挑一个最不惨的组合——像没带伞的人按「可能下雨」而不是「预报多云」来决定穿什么。代价是：如果集合画得比真实误差大，你就会为一堆根本不会发生的坏情况白白付保守费。</span></p><h3 id="最坏情况不是压力测试情景" tabindex="-1">最坏情况不是压力测试情景 <a class="header-anchor" href="#最坏情况不是压力测试情景" aria-label="Permalink to &quot;最坏情况不是压力测试情景&quot;">​</a></h3><p>压力测试指定一个经济情景。稳健集是统计邻域，最坏 \\(\\mu\\) 往往是与当前 \\(w\\) 最敌对的方向，没有叙事。两者都要：稳健防估计误差，情景防结构破裂。不要用稳健优化替代 <a href="/quant/stress-reverse-stress">压力</a>。</p><p><span class="marginnote">\\(\\Sigma\\) 也可以进不确定集。只稳健 \\(\\mu\\)、把 \\(\\Sigma\\) 当已知，在高维里仍可能不够；但双线性最坏更难算，实务常只稳健 \\(\\mu\\) 并对 \\(\\Sigma\\) 收缩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选集合：椭圆（有二次锥表示）或盒。半径用交叉验证或与 BL \\(\\tau\\) 对齐。求解：SOCP/QP，见 Goldfarb–Iyengar。输出对照：Markowitz 点估计、贝叶斯后验、稳健 maximin 的权重与样本外。若稳健解接近 100% 现金，说明半径太大或 \\(\\hat\\mu\\) 相对费用没有边。</p>',12)),(e(),s(l,null,{default:t(()=>[n(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E9%80%89%E9%9B%86%E5%90%88%E5%87%A0%E4%BD%95%22%5D%20--%3E%20B%5B%22%E7%9B%92%EF%BC%9A%E6%AF%8F%E4%B8%AA%20%CE%BC%E1%B5%A2%20%E5%8D%95%E7%8B%AC%E7%BB%99%E8%AF%AF%E5%B7%AE%E7%95%8C%20%CE%B4%E1%B5%A2%22%5D%0A%20%20S%20--%3E%20E%5B%22%E6%A4%AD%E5%9C%86%EF%BC%9A%E8%AF%AF%E5%B7%AE%E9%A2%84%E7%AE%97%E5%9C%A8%E8%B5%84%E4%BA%A7%E9%97%B4%E5%85%B1%E4%BA%AB%22%5D%0A%20%20B%20--%3E%20SOL%5B%22SOCP%2FQP%20%E6%B1%82%20maximin%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20E%20--%3E%20SOL%0A%20%20SOL%20--%3E%20OUT%5B%22%E5%AF%B9%E7%85%A7%E7%82%B9%E4%BC%B0%E8%AE%A1%E4%B8%8E%E8%B4%9D%E5%8F%B6%E6%96%AF%E7%9A%84%E6%9D%83%E9%87%8D%22%5D%0A%20%20OUT%20--%3E%20DIAG%7B%22%E7%A8%B3%E5%81%A5%E8%A7%A3%E6%8E%A5%E8%BF%91%E5%85%A8%E7%8E%B0%E9%87%91%EF%BC%9F%22%7D%0A%20%20DIAG%20--%3E%7C%22%E6%98%AF%22%7C%20RAD%5B%22%E5%8D%8A%E5%BE%84%E8%BF%87%E5%A4%A7%E6%88%96%20%CE%BC%CC%82%20%E6%97%A0%E8%BE%B9%EF%BC%9A%E5%9B%9E%E7%82%89%E6%A0%A1%E5%87%86%22%5D%0A%20%20DIAG%20--%3E%7C%22%E5%90%A6%22%7C%20KEEP%5B%22%E8%BF%9B%E6%A0%B7%E6%9C%AC%E5%A4%96%E6%A3%80%E9%AA%8C%E5%90%8E%E7%95%99%E7%94%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"DRO/Wasserstein：不确定集是分布的 Wasserstein 球，极限含 CVaR 型惩罚。与本课盒/椭圆是同一精神的不同几何，不在这里重写前沿课。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"内层 min 把 \\(w^\\top\\mu\\) 减掉一个与 \\(\\|w\\|\\) 成正比的罚（椭圆时是 \\(\\sqrt{w^\\top\\Sigma_\\mu w}\\)）。于是稳健 Markowitz 像在更大的风险厌恶下做，或像在协方差上加了一层。这解释了为何看起来像「再收缩一次」。政策含义：不确定越大，越接近最小方差或均衡，与贝叶斯同向，机制是 min 而不是积分。",-1)),(e(),s(l,null,{default:t(()=>[n(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E4%B8%8D%E7%A1%AE%E5%AE%9A%E9%9B%86%20U%22%5D%20--%3E%20Inner%5B%22%E5%AF%B9%20%CE%BC%20%E5%8F%96%E6%9C%80%E5%9D%8F%22%5D%0A%20%20Inner%20--%3E%20W%5B%22maximin%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20Rad%5B%22%E5%8D%8A%E5%BE%84%E6%A0%A1%E5%87%86%22%5D%20--%3E%20U%0A%20%20Rad%20--%3E%20Oos%5B%22%E7%94%A8%E6%A0%B7%E6%9C%AC%E5%A4%96%E6%95%88%E7%94%A8%E9%80%89%E5%8D%8A%E5%BE%84%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>集合几何选错（盒 vs 椭圆）会改变最坏方向。稳健对「均值附近的对抗」有效，对 2008 那种结构断裂无效。计算上的近似（线性化最坏）可能比点估计更脆。不要把稳健最优当成保证下限——它只对你写的集合保证。</p><p><span class="marginnote">初学者容易把「稳健最优」当成保本承诺：实际上它只对你亲手写下的不确定集保证。真实发生的不利 \\(\\mu\\) 完全可以落在你的椭圆外——2008 年不是「均值估偏了一点」，而是相关性结构整个换掉，这类破裂在统计邻域之外，得靠压力情景另防。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稳健组合是 maximin：半径是偏好，应用样本外校准。</li><li>与贝叶斯同向收缩，机制是最坏而不是后验平均。</li><li>不能替代宏观压力情景。</li><li>出处：Goldfarb and Iyengar, <em>Mathematics of Operations Research</em>, 2003。</li></ul>',5))])}const b=A(d,[["render",p]]);export{_ as __pageData,b as default};
